import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { ImageResponse } from "next/og";
import {
  themeById,
  headlineSize,
  splitAccent,
  layoutById,
  SLIDE_W,
  SLIDE_H,
  type SlideTheme,
} from "@/lib/slides/design";
import { getPhotoBytes } from "@/lib/photos/queries";

export const runtime = "nodejs";

/**
 * One carousel slide, as a PNG.
 *
 * Rendered rather than generated by an image model, on purpose: a slide is
 * mostly words, and image models misspell words. The photograph behind the
 * text is real, from the person's own bank, and the text is drawn over it
 * sharply at Instagram's full portrait size.
 *
 * Four layouts, not fourteen. A deck reads as one thing because a few
 * arrangements repeat.
 */

let fontCache: Record<string, ArrayBuffer> | null = null;
async function fonts() {
  if (fontCache) return fontCache;
  const dir = join(process.cwd(), "assets", "fonts");
  const [cond, body, heavy] = await Promise.all([
    readFile(join(dir, "BigShoulders-Bold.ttf")),
    readFile(join(dir, "Inter-SemiBold.otf")),
    readFile(join(dir, "Inter-ExtraBold.otf")),
  ]);
  const ab = (b: Buffer) =>
    b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) as ArrayBuffer;
  fontCache = { cond: ab(cond), body: ab(body), heavy: ab(heavy) };
  return fontCache;
}

let logoCache: string | null | undefined;
async function logo(): Promise<string | null> {
  if (logoCache !== undefined) return logoCache;
  try {
    const f = await readFile(join(process.cwd(), "assets", "brand", "riseup-logo.png"));
    logoCache = `data:image/png;base64,${f.toString("base64")}`;
  } catch {
    logoCache = null;
  }
  return logoCache;
}

/**
 * Satori cannot fetch a URL, so the photo is inlined. Read straight from
 * the database rather than through our own HTTP route, which would mean a
 * slide render waiting on a second request to ourselves.
 */
async function photoDataUri(id: number | null): Promise<string | null> {
  if (!id) return null;
  try {
    const p = await getPhotoBytes(id);
    return p ? `data:${p.mime};base64,${p.bytes.toString("base64")}` : null;
  } catch {
    return null;
  }
}

function Headline({
  text,
  accent,
  size,
  t,
}: {
  text: string;
  accent: string | null;
  size: number;
  t: SlideTheme;
}) {
  const { before, hit, after } = splitAccent(text, accent);
  return (
    <div
      style={{
        display: "flex",
        flexWrap: "wrap",
        fontFamily: "Cond",
        fontSize: size,
        lineHeight: 0.92,
        color: t.ink,
        textTransform: "uppercase",
        letterSpacing: -0.5,
      }}
    >
      <span>{before}</span>
      {hit && <span style={{ color: t.accent }}>{hit}</span>}
      {after && <span>{after}</span>}
    </div>
  );
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const text = (searchParams.get("text") ?? "").slice(0, 400);
  const sub = (searchParams.get("sub") ?? "").slice(0, 400);
  const accent = searchParams.get("accent");
  const index = Number(searchParams.get("i") ?? "1");
  const total = Number(searchParams.get("n") ?? "1");
  const handle = (searchParams.get("handle") ?? "").slice(0, 40);
  const photoId = Number(searchParams.get("photo") ?? "") || null;
  const t = themeById(searchParams.get("theme"));
  const layout = layoutById(searchParams.get("layout"));

  const [f, logoSrc, photo] = await Promise.all([
    fonts(),
    logo(),
    photoDataUri(photoId),
  ]);

  // A layout that wants a photo and has none falls back rather than
  // rendering an empty frame where the picture should be.
  const mode = photo ? layout : "plain";
  const isHook = index === 1;
  const isLast = total > 1 && index === total;
  const narrow = mode === "portrait";
  const size = headlineSize(text, narrow);

  const Footer = (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        position: "absolute",
        left: 72,
        right: 72,
        bottom: 56,
      }}
    >
      <div style={{ display: "flex", alignItems: "center" }}>
        {(isHook || isLast) && t.logo && logoSrc ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={logoSrc} width={300} alt="" />
        ) : (
          <div style={{ display: "flex", fontFamily: "Body", fontSize: 24, color: t.dim }}>
            {handle ? `@${handle.replace(/^@/, "")}` : ""}
          </div>
        )}
      </div>
      <div style={{ display: "flex", fontFamily: "Body", fontSize: 24, color: t.dim, letterSpacing: 2 }}>
        {total > 1 ? `${index} / ${total}` : ""}
      </div>
    </div>
  );

  const Progress = total > 1 && (
    <div style={{ display: "flex", flexDirection: "column", position: "absolute", top: 0, left: 0, width: SLIDE_W }}>
      <div style={{ display: "flex", width: "100%", height: 8 }}>
        <div style={{ display: "flex", width: `${Math.round((index / total) * 100)}%`, background: t.accent }} />
      </div>
      <div style={{ display: "flex", width: "100%", height: 2, background: t.trim, opacity: 0.45 }} />
    </div>
  );

  const Sub = sub ? (
    <div style={{ display: "flex", flexDirection: "column", marginTop: 30 }}>
      <div style={{ display: "flex", width: 300, height: 2, background: t.trim, marginBottom: 26 }} />
      <div
        style={{
          display: "flex",
          fontFamily: "Body",
          fontSize: narrow ? 25 : 28,
          lineHeight: 1.45,
          color: t.dim,
          maxWidth: narrow ? 430 : 760,
        }}
      >
        {sub}
      </div>
    </div>
  ) : null;

  // --- the four arrangements ------------------------------------------
  let body: React.ReactElement;

  if (mode === "portrait") {
    body = (
      <div style={{ display: "flex", width: "100%", height: "100%", position: "relative" }}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={photo!}
          alt=""
          style={{ position: "absolute", right: 0, top: 0, width: 660, height: SLIDE_H, objectFit: "cover" }}
        />
        {/* A wash so the headline always has something to sit on, whatever
            the photograph happens to be doing behind it. */}
        <div
          style={{
            position: "absolute", left: 0, top: 0, width: 700, height: SLIDE_H, display: "flex",
            backgroundImage: `linear-gradient(to right, ${t.bg} 58%, transparent)`,
          }}
        />
        <div style={{ display: "flex", flexDirection: "column", position: "absolute", left: 72, top: 300, width: 480 }}>
          <Headline text={text} accent={accent} size={size} t={t} />
          {Sub}
        </div>
      </div>
    );
  } else if (mode === "band") {
    body = (
      <div style={{ display: "flex", flexDirection: "column", width: "100%", height: "100%" }}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={photo!} alt="" style={{ width: SLIDE_W, height: 620, objectFit: "cover" }} />
        <div style={{ display: "flex", flexDirection: "column", padding: "64px 72px 0 72px", flex: 1 }}>
          <Headline text={text} accent={accent} size={size} t={t} />
          {Sub}
        </div>
      </div>
    );
  } else if (mode === "full") {
    body = (
      <div style={{ display: "flex", width: "100%", height: "100%", position: "relative" }}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={photo!} alt="" style={{ position: "absolute", inset: 0, width: SLIDE_W, height: SLIDE_H, objectFit: "cover" }} />
        <div
          style={{
            position: "absolute", inset: 0, display: "flex", width: SLIDE_W, height: SLIDE_H,
            backgroundImage: `linear-gradient(to top, ${t.bg} 10%, rgba(0,0,0,0.55) 55%, rgba(0,0,0,0.25))`,
          }}
        />
        <div style={{ display: "flex", flexDirection: "column", position: "absolute", left: 72, right: 72, bottom: 190 }}>
          <Headline text={text} accent={accent} size={size} t={t} />
          {Sub}
        </div>
      </div>
    );
  } else {
    body = (
      <div
        style={{
          display: "flex", flexDirection: "column", width: "100%", height: "100%",
          padding: "0 72px", justifyContent: "center",
        }}
      >
        <Headline text={text} accent={accent} size={size} t={t} />
        {Sub}
      </div>
    );
  }

  return new ImageResponse(
    (
      <div style={{ width: "100%", height: "100%", display: "flex", background: t.bg, position: "relative", fontFamily: "Body" }}>
        {body}
        {Progress}
        {Footer}
      </div>
    ),
    {
      width: SLIDE_W,
      height: SLIDE_H,
      fonts: [
        { name: "Cond", data: f.cond, weight: 700, style: "normal" },
        { name: "Body", data: f.body, weight: 600, style: "normal" },
        { name: "Body", data: f.heavy, weight: 800, style: "normal" },
      ],
      headers: { "Cache-Control": "private, max-age=86400" },
    },
  );
}
